      <div class="input-group-append">
        {{ append }}
      </div>
      {%- endif -%}
      {% if direct_error %}
        <div class="invalid-feedback">
          <ul class="form-text text-danger {% if field.widget.input_type == 'checkbox' %}mt-0{% endif %}">
          {% for e in field.errors if e is string %}
            <li>{{ e }}</li>
          {% endfor %}
          </ul>
        </div>
